struct T {
  T() { std::cout << "ctor "; }
  T(const T&) { std::cout << "copy "; }
  T(T&&) { std::cout << "move "; }
  ~T() { std::cout << "dtor "; }
};
T build() {
  T result;
  return std::move(result);
}
int main() { T t = build(); }

T build() {
  T result;
  return result;   // NRVO, else implicit move
}

int main() { T t = build(); }   // ctor dtor

struct NM {
  int v;
  explicit NM(int x) : v(x) {}
  NM(const NM&) = delete;
  NM(NM&&) = delete;
};
NM f1() { return NM{1}; }
NM f2() { NM x{1}; return x; }

struct Str {  // logs "copy " / "move "
  Str() = default;
  Str(const Str&) { printf("copy "); }
  Str(Str&&) noexcept { printf("move "); }
};
struct Order {
  Str id_;
  Order(const Str& id) : id_(id) {}
};
Str s, t;
Order a(s);
Order b(std::move(t));
Order c(Str{});
